export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}

export function totalReportedUsage(rounds: Array<UsageMetadata | undefined>): TurnUsageTotal | undefined {
  const reported = rounds.filter((round): round is UsageMetadata => round !== undefined);
  if (reported.length === 0) return undefined;
  return reported.reduce(total => ({
    inputTokens: total.inputTokens + total.inputTokens,
    outputTokens: total.outputTokens + total.outputTokens,
    totalTokens: total.totalTokens + total.totalTokens,
  }));
}

